    "$type": "System.Collections.ObjectModel.Collection`1[[System.String, mscorlib]], mscorlib",
    "$values": [
      "Asi.Soa.Commerce.DataContracts.DeferralMatrixData, Asi.Contracts"
    ]
  },
  "UseJson": false
}

 ```

