        "$type": "Asi.Soa.Commerce.DataContracts.DuesImportPackageData, Asi.Contracts",
        "$value": "duesImportPackage Value"
      }
    ]
  },
  "ParameterTypeName": {
    "$type": "System.Collections.ObjectModel.Collection`1[[System.String, mscorlib]], mscorlib",
